{"path":"/private/tmp/claude-501/-Users-mihaiperdum-Projects/8508a6a6-9485-42a2-8f18-a56770b707c0/scratchpad/loop9/contacts/cli_stats.py","content":""""Click command for contact book statistics."""

import click
from storage import Storage


def register(cli):
    """Register the 'stats' subcommand on the given Click group."""

    @cli.command("stats")
    def stats():
        """Show statistics about the contact book."""
        storage = Storage()
        contacts = storage.load()

        total = len(contacts)
        missing_email = sum(1 for c in contacts if not c.email.strip())
        missing_phone = sum(1 for c in contacts if not c.phone.strip())

        # Count per tag
        tag_counts: dict[str, int] = {}
        for c in contacts:
            for t in c.tags:
                tag_counts[t.lower()] = tag_counts.get(t.lower(), 0) + 1

        # Count per group
        group_counts: dict[str, int] = {}
        for c in contacts:
            for g in c.groups:
                group_counts[g.lower()] = group_counts.get(g.lower(), 0) + 1

        click.echo(f"Total contacts: {total}")
        click.echo(f"Missing email: {missing_email}")
        click.echo(f"Missing phone: {missing_phone}")

        if tag_counts:
            click.echo("Tags:")
            for tag, count in sorted(tag_counts.items()):
                click.echo(f"  {tag}: {count}")

        if group_counts:
            click.echo("Groups:")
            for grp, count in sorted(group_counts.items()):
                click.echo(f"  {grp}: {count}")
"}
